#include <stdbool.h>
#include <stdlib.h>

#define SIGMA 26

struct Trie {
    struct Trie *ch[SIGMA];
    bool end;
};

static struct Trie *node(void) {
    struct Trie *t = calloc(1, sizeof *t);
    if (!t) abort();
    return t;
}

void insert(struct Trie *root, const char *s) {
    struct Trie *t = root;
    for (; *s; s++) {
        int c = *s - 'a';
        if (!t->ch[c]) t->ch[c] = node();
        t = t->ch[c];
    }
    t->end = true;
}

static const struct Trie *walk(const struct Trie *t, const char *s) {
    for (; t && *s; s++) t = t->ch[*s - 'a'];
    return t;                         /* NULL if the path breaks */
}

bool search(const struct Trie *root, const char *s) {
    const struct Trie *t = walk(root, s);
    return t && t->end;
}

bool starts_with(const struct Trie *root, const char *p) {
    return walk(root, p) != NULL;
}

static bool is_empty(const struct Trie *t) {
    for (int i = 0; i < SIGMA; i++) if (t->ch[i]) return false;
    return true;
}

/* returns true if the caller should free and unlink t */
static bool del(struct Trie *t, const char *s) {
    if (!*s) {
        if (!t->end) return false;           /* word not present */
        t->end = false;
        return is_empty(t);
    }
    int c = *s - 'a';
    if (!t->ch[c]) return false;
    if (del(t->ch[c], s + 1)) {
        free(t->ch[c]);
        t->ch[c] = NULL;
        return !t->end && is_empty(t);
    }
    return false;
}

#include <stdio.h>

static void collect(const struct Trie *t, char *buf, int len) {
    if (t->end) { buf[len] = '\0'; puts(buf); }
    for (int i = 0; i < SIGMA; i++)
        if (t->ch[i]) { buf[len] = (char)('a' + i); collect(t->ch[i], buf, len + 1); }
}

struct B { struct B *c[2]; };

unsigned best_xor(const struct B *t, unsigned x) {
    unsigned r = 0;
    for (int b = 31; b >= 0; b--) {
        int bit = (x >> b) & 1;
        if (t->c[!bit]) { r |= 1u << b; t = t->c[!bit]; }
        else t = t->c[bit];
    }
    return r;
}
